@Test
public void shouldDetermineEndpointParameters() {
    final CamelContext camelContext = mock(CamelContext.class);
    final RestOpenApiComponent component = new RestOpenApiComponent();
    component.setCamelContext(camelContext);
    final RestOpenApiEndpoint endpoint = new RestOpenApiEndpoint("uri", "remaining", component, Collections.emptyMap());
    endpoint.setHost("http://petstore.openapi.io");
    final OpenAPI openapi = new OpenAPI();
    final Operation operation = new Operation().operationId("get");
    assertThat(endpoint.determineEndpointParameters(openapi, operation)).containsOnly(entry("host", "http://petstore.openapi.io"));
    component.setComponentName("xyz");
    assertThat(endpoint.determineEndpointParameters(openapi, operation)).containsOnly(entry("host", "http://petstore.openapi.io"), entry("producerComponentName", "xyz"));
    List<String> consumers = new ArrayList<String>();
    consumers.add("application/json");
    List<String> produces = new ArrayList<String>();
    produces.add("application/xml");
    //        operation.requestBody = operation.createRequestBody();
    //        operation.responses = operation.createResponses();
    //        operation.responses.addResponse("200", operation.responses.createResponse("200"));
    for (String consumer : consumers) {
        // MediaType object should be schema?
        operation.requestBody(new RequestBody().content(new Content().addMediaType(consumer, new MediaType())));
    }
    ApiResponses apiResponses = new ApiResponses();
    operation.responses(apiResponses);
    // Can only have one content per response...
    for (String produce : produces) {
        apiResponses.addApiResponse("200", new ApiResponse().content(new Content().addMediaType(produce, new MediaType())));
    }
    assertThat(endpoint.determineEndpointParameters(openapi, operation)).containsOnly(entry("host", "http://petstore.openapi.io"), entry("producerComponentName", "xyz"), entry("consumes", "application/xml"), entry("produces", "application/json"));
    component.setProduces("application/json");
    component.setConsumes("application/atom+xml");
    assertThat(endpoint.determineEndpointParameters(openapi, operation)).containsOnly(entry("host", "http://petstore.openapi.io"), entry("producerComponentName", "xyz"), entry("consumes", "application/atom+xml"), entry("produces", "application/json"));
    endpoint.setProduces("application/atom+xml");
    endpoint.setConsumes("application/json");
    assertThat(endpoint.determineEndpointParameters(openapi, operation)).containsOnly(entry("host", "http://petstore.openapi.io"), entry("producerComponentName", "xyz"), entry("consumes", "application/json"), entry("produces", "application/atom+xml"));
    endpoint.setComponentName("zyx");
    assertThat(endpoint.determineEndpointParameters(openapi, operation)).containsOnly(entry("host", "http://petstore.openapi.io"), entry("producerComponentName", "zyx"), entry("consumes", "application/json"), entry("produces", "application/atom+xml"));
    Parameter parameter1 = new Parameter().name("q").in("query").required(true);
    operation.addParametersItem(parameter1);
    assertThat(endpoint.determineEndpointParameters(openapi, operation)).containsOnly(entry("host", "http://petstore.openapi.io"), entry("producerComponentName", "zyx"), entry("consumes", "application/json"), entry("produces", "application/atom+xml"), entry("queryParameters", "q={q}"));
    Parameter parameter2 = new Parameter().name("o").in("query");
    operation.addParametersItem(parameter2);
    assertThat(endpoint.determineEndpointParameters(openapi, operation)).containsOnly(entry("host", "http://petstore.openapi.io"), entry("producerComponentName", "zyx"), entry("consumes", "application/json"), entry("produces", "application/atom+xml"), entry("queryParameters", "q={q}&o={o?}"));
}

