@Test
public void testMuteException() throws Exception {
    WebRequest req = new PostMethodWebRequest(contextUrl + "/services/mute", new ByteArrayInputStream("".getBytes()), "text/plain");
    Appender appender = mock(Appender.class);
    when(appender.getName()).thenReturn("mockAppender");
    when(appender.isStarted()).thenReturn(true);
    Logger logger = (Logger) LogManager.getLogger(DefaultHttpBinding.class);
    logger.addAppender(appender);
    query(req, false);
    ArgumentCaptor<LogEvent> captor = ArgumentCaptor.forClass(LogEvent.class);
    verify(appender, atLeastOnce()).append(captor.capture());
    assertTrue(captor.getAllValues().stream().anyMatch(event -> event.getMessage().getFormattedMessage().equals("Server internal error response returned due to 'Camel cannot do this'")));
}

